from scipy.optimize import minimize_scalar
def build(w, spec):
    cs=np.cos(w*t); sn=np.sin(w*t)
    T={"1":np.ones_like(t),"c":cs,"s":sn}
    return np.column_stack([x**i*v**j*T[tn] for (i,j,tn) in spec])
spec=[(0,0,"1"),(1,0,"1"),(2,0,"1"),(3,0,"1"),(0,1,"1"),(1,1,"1"),(0,0,"c"),(0,0,"s"),(1,0,"s"),(2,0,"c"),(0,2,"s"),(3,0,"c")]
def loss(w):
    A=build(w,spec); c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
    return np.mean((dv_dt-A@c)**2)/np.var(dv_dt)
